              write_v_dc_half => write_v_dc_half,  -- sfix24_En18
              write_Ld_Ts => write_Ld_Ts,  -- sfix24_En18
              write_Lq_Ts => write_Lq_Ts,  -- sfix24_En18
              reset_internal => reset_internal  -- ufix1
              );

  ip_timestamp <= unsigned'(X"9B3A072E");

  reset_cm <=  NOT IPCORE_RESETN;

  reset_before_sync <= reset_cm OR reset_internal;

  AXI4_BID <= AXI4_BID_tmp;

  AXI4_BRESP <= AXI4_BRESP_tmp;

  AXI4_RID <= AXI4_RID_tmp;

  AXI4_RDATA <= AXI4_RDATA_tmp;

  AXI4_RRESP <= AXI4_RRESP_tmp;

END rtl;

